export type MatchType='STRONG_MATCH'|'SIMILAR_ALTERNATIVE'|'DESIGN_ALTERNATIVE'|'NO_SUPPORTED_MATCH';
export interface ProductProfile { productName:string|null; brand:string|null; category:'chair'|'table'|'lighting'|'unknown'; price:number|null; currency:'USD'|null; dimensions:{width:number|null;height:number|null;depth:number|null}; materials:string[]; construction:string[]; styleDescriptors:string[]; notableFeatures:string[]; warranty:string|null; sourceImage:string|null; sourceUrl:string|null; evidence?:Array<{url:string;title:string|null;excerpt:string}>; }
export interface ComparisonResult { id:string; original:ProductProfile; alternative:ProductProfile|null; similarity_score:number|null; confidence_score:number; match_type:MatchType; similarities:string[]; differences:string[]; editorial:string; review_status:'DEMO'|'AI_ASSISTED'; cache_hit:boolean; }
